<template><SuperAdminLayout><main v-if="ticket" class="ticket-detail"><header><div><h1>Open Ticket</h1><p>View and manage one customer support ticket</p></div><div class="actions"><RouterLink to="/super-admin/support">←&nbsp; Back to Tickets</RouterLink><button @click="choose('reply')">▱&nbsp; Reply to Customer</button><button @click="choose('note')">▧&nbsp; Add Internal Note</button><button class="pending" @click="choose('pending')">◷&nbsp; Mark Pending</button><button class="resolve" @click="choose('resolve')">✓&nbsp; Resolve</button><button class="close" @click="choose('close')">⊗&nbsp; Close Ticket</button></div></header><section class="box"><h2>A. Ticket Information</h2><dl><div v-for="(value,label) in info" :key="label"><dt>{{label}}</dt><dd><span v-if="label==='Priority'||label==='Status'" :class="['pill',classFor(value)]">{{value}}</span><template v-else>{{value}}</template></dd></div></dl><div class="bottom-info"><div><b>Received Date &amp; Time</b><strong>{{format(ticket.sent_at)}}</strong></div><div><b>Attachments</b><span class="attachment">▧ No attachment supplied</span></div><div class="details"><b>Ticket Details</b><p>{{ticket.description||'—'}}</p></div></div></section><div class="split"><section class="box communication"><h2>B. Ticket Communication History</h2><div class="table-wrap"><table><thead><tr><th>No.</th><th>Date - Time</th><th>Sent By</th><th>Type</th><th>Details</th><th>Status</th></tr></thead><tbody><tr v-for="(row,index) in activities" :key="row.id"><td>{{index+1}}</td><td>{{format(row.created_at)}}</td><td>{{row.actor_name||'Customer'}}</td><td>{{row.activity_type}}</td><td>{{row.message||'—'}}</td><td><span :class="['pill',classFor(row.status)]">{{row.status}}</span></td></tr><tr v-if="!activities.length"><td colspan="6" class="empty">No communication records yet.</td></tr></tbody></table></div></section><section class="box response"><h2>C. Staff Response</h2><div class="response-grid"><label>Response Type<select v-model="action"><option value="reply">Reply to Customer</option><option value="note">Add Internal Note</option><option value="pending">Mark Pending</option><option value="resolve">Resolve</option><option value="close">Close Ticket</option></select></label><label>Response Method<select><option>Email</option><option>Phone</option><option>Portal message</option></select></label><label>Staff Name<input :value="staffName" readonly></label><label>Staff Badge No.<input value="Super Admin" readonly></label></div><label>Message / Reply<textarea v-model="message" placeholder="Write your response or internal note…"></textarea></label><button class="submit" @click="submit">Save {{actionLabel}}</button></section></div><section class="box final"><h2>D. Final Result</h2><div class="final-fields"><label>Final Result<select v-model="finalResult"><option value="">Select final result</option><option>Issue Resolved</option><option>Closed Successfully</option><option>Customer Informed</option></select></label><label>Final Result Details<textarea v-model="finalDetails" placeholder="Enter final result details…"></textarea></label><label>Closed By Staff Name<input :value="staffName" readonly></label><label>Closed Date<input :value="today" readonly></label></div><p class="notice">ⓘ&nbsp; This ticket is currently <b>{{ticket.status}}</b>. Final result and closure details will be completed when the ticket is resolved.</p></section></main><p v-else class="loading">Loading ticket…</p></SuperAdminLayout></template>
<script setup>import{computed,onMounted,ref}from'vue';import{RouterLink,useRoute}from'vue-router';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';import{authState}from'../store/auth';const route=useRoute(),ticket=ref(null),activities=ref([]),action=ref('reply'),message=ref(''),finalResult=ref(''),finalDetails=ref(''),today=new Date().toLocaleDateString(),staffName=computed(()=>authState.user?.name||'Super Admin'),actionLabel=computed(()=>({reply:'Reply',note:'Note',pending:'Pending Update',resolve:'Resolution',close:'Closure'}[action.value])),format=v=>v?new Date(v).toLocaleString():'—',classFor=v=>String(v||'').toLowerCase().replaceAll(' ','-'),info=computed(()=>ticket.value?{'Ticket No.':ticket.value.ticket_no,'Sent Date':format(ticket.value.sent_at),'Customer Account':ticket.value.customer,'Company Name':ticket.value.customer,'Sent By (Customer)':ticket.value.customer_name,'Customer Admin Name':ticket.value.customer_name,Email:ticket.value.email||'—','Phone No.':ticket.value.phone||'—','Ticket Type':ticket.value.type,Subject:ticket.value.subject,Priority:ticket.value.priority,'Assigned To':ticket.value.assigned_to,Status:ticket.value.status}:{ });function choose(value){action.value=value;document.querySelector('.response')?.scrollIntoView({behavior:'smooth',block:'center'})}async function load(){const{data}=await client.get('/super-admin/tickets/'+route.params.id);ticket.value=data.data.ticket;activities.value=data.data.activities||[]}async function submit(){await client.post('/super-admin/tickets/'+route.params.id+'/actions',{action:action.value,message:message.value||finalDetails.value});message.value='';await load()}onMounted(load)</script>
<style scoped>.ticket-detail{color:#071d63}.ticket-detail>header{display:flex;justify-content:space-between;gap:15px;align-items:start;margin-bottom:17px}.ticket-detail h1{margin:0;font-size:2rem}.ticket-detail header p{margin:4px 0;color:#5e7096}.actions{display:flex;flex-wrap:wrap;gap:10px;justify-content:flex-end}.actions a,.actions button{height:48px;box-sizing:border-box;display:inline-flex;align-items:center;border:1px solid #d6e0f1;border-radius:6px;background:#fff;color:#071d63;padding:0 15px;font-weight:700;text-decoration:none}.actions .pending{color:#e86e00}.actions .resolve{color:#078338}.actions .close{color:#e51f28}.box{background:#fff;border:1px solid #dce5f3;border-radius:8px;padding:14px;margin-bottom:12px}.box h2{font-size:1rem;margin:0 0 11px}dl{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid #dae3ef;margin:0}dl div{padding:9px 16px;border:1px solid #e4ebf4;min-height:35px}dt,.bottom-info b,.response label,.final-fields label{display:block;font-size:.68rem;font-weight:800}dd{margin:6px 0 0;font-size:.82rem;font-weight:700;word-break:break-word}.pill{display:inline-block;min-width:55px;padding:3px 8px;border-radius:5px;text-align:center;background:#edf5ff;color:#0755dc;border:1px solid #d4e3fa}.high{color:#e21a1a;background:#fff0f0;border-color:#ffd3d3}.pending{color:#ed7200;background:#fff6eb}.resolved{color:#078338;background:#eaf9ef}.closed{color:#46546e;background:#f0f3f7}.bottom-info{display:grid;grid-template-columns:1fr 1.8fr 3.5fr;border:1px solid #e4ebf4;border-top:0}.bottom-info>div{padding:10px 16px;border-right:1px solid #e4ebf4}.bottom-info strong{display:block;margin-top:6px;font-size:.82rem}.attachment{display:inline-block;margin-top:5px;padding:5px 8px;border:1px solid #d7e1ef;border-radius:5px;font-size:.75rem}.details p{margin:5px 0 0;font-size:.78rem;line-height:1.45}.split{display:grid;grid-template-columns:3fr 2fr;gap:12px}.communication{overflow:hidden}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.75rem}th{background:linear-gradient(90deg,#06235f,#063887);color:#fff;white-space:nowrap}th,td{border:1px solid #dae3ef;padding:8px;text-align:left}td{font-weight:600}.empty{text-align:center;padding:24px}.response-grid,.final-fields{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.response label{margin-bottom:10px}.response input,.response select,.response textarea,.final-fields input,.final-fields select,.final-fields textarea{width:100%;box-sizing:border-box;border:1px solid #cad8ed;border-radius:6px;padding:9px;margin-top:5px;color:#0b2160;background:#fff}.response textarea{height:130px;resize:vertical}.submit{background:#062c72;color:#fff;border:0;border-radius:5px;padding:10px 15px;font-weight:700}.final-fields{grid-template-columns:1.1fr 2.5fr 1fr 1fr}.final-fields textarea{height:38px;resize:vertical}.notice{margin:12px 0 0;padding:10px;border-radius:5px;background:#edf4ff;color:#0d378c;font-size:.77rem}.loading{padding:30px}@media(max-width:1000px){dl{grid-template-columns:repeat(3,1fr)}.split{grid-template-columns:1fr}.final-fields{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.ticket-detail>header{display:block}.actions{justify-content:flex-start;margin-top:14px}.bottom-info,.response-grid{grid-template-columns:1fr}.bottom-info>div{border-bottom:1px solid #e4ebf4}.final-fields,dl{grid-template-columns:1fr}}@media print{.sa-sidebar,.sa-topbar,.actions,.response,.notice{display:none!important}}</style>
